/// <summary>
/// The compensation's wakeup, and it TAKES ITS CHOICE FROM THE OTHER SLICE deliberately.
///
/// Mixing the two would be incoherent rather than flexible: in-request execution with an out-of-request
/// compensation means the caller waits for a refusal and then leaves without giving the unit back, so the
/// mode that has no daemon would depend on one for its recovery. The two steps of the Reservation Pattern
/// are one decision, so <see cref="IssueGrantWakeup.Chosen"/> is read here rather than a second setting
/// being invented. A second setting would be a second place the same fact lives.
///
/// The trigger event is <c>GrantRefused</c> — ours, appended in our own transaction — and losing one is
/// unacceptable: an unreleased slot is a unit of the limited resource gone for ever. By the automation
/// folder's own decision table that is the row that says <em>subscription</em>, and it is what the
/// out-of-request mode uses.
/// </summary>
public static class ReleaseSlotWakeup
{
    /// <summary>Not a separate setting. See the class comment.</summary>
    public static IssueGrantWakeup.Mechanism Chosen => IssueGrantWakeup.Chosen;

    /// <summary>Resolved by IssueGrantWakeup.Choose; this exists only because Program.cs calls both.</summary>
    public static void Choose(IConfiguration config) { }

    public static void RegisterServices(WebApplicationBuilder builder) { }

    /// <summary>Inline, for the reason argued in ViewRegistrations, unless the control test asks for the
    /// hazard. Deferred to IssueGrantWakeup so both todo Views move together — measuring one Async while
    /// the other stays Inline would compare two systems rather than two lifecycles.</summary>
    public static ProjectionLifecycle LifecycleOf(ProjectionLifecycle fallback) =>
        IssueGrantWakeup.LifecycleOf(fallback);

    public static void ConfigureMarten(StoreOptions opts) { }

    public static void ConfigureStore(MartenServiceCollectionExtensions.MartenConfigurationExpression marten)
    {
        if (Chosen != IssueGrantWakeup.Mechanism.Subscription) return;

        // AddAsyncDaemon is already called by IssueGrantWakeup and by ViewRegistrations. Calling it again
        // is harmless — Marten keeps one daemon per store — and leaving it out would make this slice's
        // registration depend on another slice remembering, which is exactly the kind of invisible
        // coupling the Configure hooks exist to avoid.
        marten.AddAsyncDaemon(DaemonMode.Solo);

        marten.AddSubscriptionWithServices<ReleaseSlotSubscription>(
            ServiceLifetime.Singleton, o => o.IncludeType<GrantRefused>());
    }

    public static void ConfigureIntegration(MartenIntegration integration) { }

    public static void ConfigureWolverine(WolverineOptions opts) { }
}

/// <summary>
/// Wakes the compensation when an execution has refused. Same shape and same reasoning as
/// <see cref="IssueGrantSubscription"/>, filtered to the one event that opens a row on this todo list.
/// </summary>
public sealed class ReleaseSlotSubscription(IServiceProvider services) : ISubscription
{
    public async Task<IChangeListener> ProcessEventsAsync(
        EventRange page,
        ISubscriptionController controller,
        IDocumentOperations operations,
        CancellationToken cancellationToken)
    {
        if (page.Events.Count == 0) return NullChangeListener.Instance;

        await using var scope = services.CreateAsyncScope();
        await scope.ServiceProvider.GetRequiredService<IMessageBus>()
            .InvokeAsync(new RunReleaseSlot(), cancellationToken);

        return NullChangeListener.Instance;
    }

    public ValueTask DisposeAsync() => new();
}
